//! The behavior-tree node module (modules/test-behavior-tree-nodes), declared
//! in a `module.yaml` and generated by arora-module-rust, built as a
//! component: its generated exports serve calls, and a control node ticks its
//! children — callables the engine holds — through the world's `host`
//! interface.

use std::rc::Rc;

use arora_behavior::Status;
use arora_behavior_tree_types::TickId;
use arora_engine::call::{CallBridge, CallError, Callable};
use arora_engine::engine::EngineBuilder;
use arora_engine::executor::component::ComponentExecutor;
use arora_engine::load::load_module_from_parts;
use arora_types::call::Call;
use arora_types::module::low::Header;
use arora_types::value::{StructureField, Value};
use uuid::Uuid;

const SUCCEED: &str = "6696f0bd-e781-40cd-aeb5-8dc616f810d2";
const SEQ: &str = "32246df6-ab5d-4f18-9221-23e28731de93";
const SEQ_CHILDREN: &str = "5b6e9515-dbcc-411d-bee9-3d8cba5fedda";

/// The header the module's build script generates from its `module.yaml`.
fn header() -> Header {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../modules/test-behavior-tree-nodes/src/arora_generated/header.json");
    let json = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    serde_json::from_str(&json).expect("the generated header parses")
}

fn engine() -> std::pin::Pin<Box<arora_engine::engine::Engine>> {
    let mut engine = EngineBuilder::new()
        .add_executor(ComponentExecutor::new().unwrap())
        .build();
    let guest = std::fs::read(env!(
        "CARGO_CDYLIB_FILE_TEST_BEHAVIOR_TREE_NODES_test_behavior_tree_nodes"
    ))
    .expect("read the behavior-tree node guest");
    load_module_from_parts(&mut engine, header(), guest.into()).expect("load the guest");
    engine
}

fn call(function: &str, args: Vec<StructureField>) -> Call {
    Call {
        module_id: Some(header().id),
        id: function.parse().unwrap(),
        args,
    }
}

#[test]
fn a_generated_export_serves_a_call() {
    let mut engine = engine();
    let result = engine.arora_call(call(SUCCEED, vec![])).unwrap();
    assert_eq!(result.ret, Value::from(Status::Success));
}

/// A child of a sequence: the status it returns when ticked.
struct Child(Status);

impl Callable for Child {
    fn call(&self, _caller: &mut dyn CallBridge) -> Result<Value, CallError> {
        Ok(Value::from(self.0))
    }
}

/// `seq` ticks its children until one does not succeed, each through
/// `arora_dispatch_indirect`, which the component makes over `host`.
#[test]
fn a_sequence_ticks_its_children_through_the_host() {
    let mut engine = engine();
    let mut children = |statuses: &[Status]| -> Vec<StructureField> {
        let ticks: Vec<Value> = statuses
            .iter()
            .map(|status| {
                let callable: Rc<dyn Callable> = Rc::new(Child(*status));
                let id = engine.arora_register_callable(callable).id;
                Value::from(TickId { callable_id: id })
            })
            .collect();
        vec![StructureField {
            id: SEQ_CHILDREN.parse::<Uuid>().unwrap(),
            value: Box::new(Value::from(ticks)),
        }]
    };
    let succeeding = children(&[Status::Success, Status::Success]);
    let failing = children(&[Status::Success, Status::Failure]);

    let result = engine.arora_call(call(SEQ, succeeding)).unwrap();
    assert_eq!(result.ret, Value::from(Status::Success));
    let result = engine.arora_call(call(SEQ, failing)).unwrap();
    assert_eq!(result.ret, Value::from(Status::Failure));
}

/// A call the generated code refuses — an argument that is not an Arora
/// Buffer, short or cut short, a parameter the function does not have — fails
/// as the guest's error, and the module goes on answering calls.
#[test]
fn a_generated_export_s_refusal_is_the_guest_s_error() {
    let mut engine = engine();
    let module = header().id;
    let succeed: Uuid = SUCCEED.parse().unwrap();

    let truncated = cut_short(
        &Value::Structure(arora_types::value::Structure {
            id: succeed,
            fields: vec![StructureField {
                id: SEQ_CHILDREN.parse().unwrap(),
                value: Box::new(Value::String("a value cut short".into())),
            }],
        }),
        5,
    );
    for arg in [&[1, 2][..], &truncated] {
        let refused = engine.dispatch(&module, &succeed, arg).unwrap_err();
        assert!(
            matches!(&refused, arora_engine::module::DispatchError::Guest { message }
                if message.contains("not an Arora Buffer")),
            "{arg:?}: {refused:?}"
        );
    }
    let extra = StructureField {
        id: SEQ_CHILDREN.parse().unwrap(),
        value: Box::new(Value::U32(1)),
    };
    let refused = engine.arora_call(call(SUCCEED, vec![extra])).unwrap_err();
    assert!(
        format!("{refused}").contains("expected 0 parameters"),
        "{refused}"
    );

    let result = engine.arora_call(call(SUCCEED, vec![])).unwrap();
    assert_eq!(result.ret, Value::from(Status::Success));
}

/// The Arora Buffer of `value`, cut `by` bytes short, its size prefix counting
/// what is left: a prefix that holds, and a value that does not.
fn cut_short(value: &Value, by: usize) -> Vec<u8> {
    let whole = arora_buffers::serde_uuid::serialize(value);
    let mut cut = whole[..whole.len() - by].to_vec();
    let len = cut.len() as u32;
    cut[..4].copy_from_slice(&len.to_le_bytes());
    cut
}
